/// <summary>Bits from a byte array, lowest bit first (the x-structures' bit fields).</summary>
public struct BitReader
{
    readonly byte[] _d;
    int _pos;

    public BitReader(byte[] d, int at)
    {
        _d = d;
        _pos = at * 8;
    }

    public int U(int n)
    {
        long v = 0;
        for (int i = 0; i < n; i++, _pos++)
            v |= (long)((_d[_pos >> 3] >> (_pos & 7)) & 1) << i;
        return (int)v;
    }

    public int S(int n)
    {
        long v = (uint)U(n);
        if (n < 32 && (v & (1L << (n - 1))) != 0)
            v -= 1L << n;
        return (int)v;
    }
}

/// <summary>Bits into a byte array, lowest bit first: the mirror of BitReader (a value's low n bits).</summary>
public struct BitWriter
{
    readonly byte[] _d;
    int _pos;

    public BitWriter(byte[] d, int at)
    {
        _d = d;
        _pos = at * 8;
    }

    public void W(int n, int v)
    {
        for (int i = 0; i < n; i++, _pos++)
        {
            int bit = (int)(((long)v >> i) & 1);
            int b = _pos >> 3, m = 1 << (_pos & 7);
            _d[b] = (byte)(bit != 0 ? _d[b] | m : _d[b] & ~m);
        }
    }
}
